arguments.command:
DBG="/tmp/symbols/libmonosgen-2.0.so.debug"

# Use readelf/objdump to find the function symbols enclosing these addresses
# Filter out ARM mapping symbols ($d, $x, $t)
for addr in 0x2f4b20 0x2f4c84; do
  echo "--- $addr ---"
  nm -n "$DBG" 2>/dev/null | grep -v '^\s*$' | grep -vE ' \$[dxt]' | awk -v a="$addr" '
    BEGIN { target = strtonum(a) }
    { 
      s = strtonum("0x" $1)
      if (s <= target) { best_addr = $1; best_name = $3; best_type = $2 }
      if (s > target) { print "  " best_name " + 0x" sprintf("%x", target - strtonum("0x" best_addr)) " [" best_type "]"; exit }
    }
  '
done

