arguments.command:
DBG="/tmp/symbols/libmonosgen-2.0.so.debug"

# Let's also check with DWARF info using readelf
# Try the actual function that contains these - checking the .symtab 
for addr in 0x2f4b20 0x2f4c84; do
  echo "--- $addr ---"
  # Find actual FUNC symbols (not mapping symbols)
  nm -n -S "$DBG" 2>/dev/null | grep -vE ' \$[dxt]' | grep ' [tTwW] ' | awk -v a="$addr" '
    BEGIN { target = strtonum(a) }
    {
      s = strtonum("0x" $1)
      if (NF >= 4) { sz = strtonum("0x" $2); name = $4 } else { sz = 0; name = $3 }
      if (s <= target && (sz == 0 || s + sz > target)) { 
        best_addr = s; best_name = name; best_sz = sz 
      }
      if (s > target) { 
        printf "  %s + 0x%x", best_name, target - best_addr
        if (best_sz > 0) printf " (size: 0x%x)", best_sz
        printf "\n"
        exit 
      }
    }
  '
done

